input.command:
cd /work; cat > spec.json <<'EOF'
{
  "title": "Acute respiratory illness in Germany: does every year follow the same cycle?",
  "subtitle": "Each row is one ISO year; ARE consultation incidence peaks every winter (roughly weeks 48–12) and is lowest in summer, but peak timing and height vary between years. Source: RKI ARE-Praxis-Sentinel, CC BY 4.0",
  "arrangement": "vertical",
  "views": [
    {
      "tracks": [
        {
          "title": "ARE consultations per 100,000 per week",
          "data": {
            "url": "https://raw.githubusercontent.com/robert-koch-institut/ARE-Konsultationsinzidenz/65ac2d278c06333808415795d65f0347c54be638/ARE-Konsultationsinzidenz.tsv",
            "type": "csv-time",
            "separator": "\t",
            "dateFields": ["Kalenderwoche"]
          },
          "dataTransform": [
            { "type": "filter", "field": "Bundesland", "oneOf": ["Bundesweit"] },
            { "type": "filter", "field": "Altersgruppe", "oneOf": ["00+"] }
          ],
          "mark": "rect",
          "x": { "field": "Kalenderwoche", "type": "temporal", "period": { "unit": "year", "weekBased": true, "newField": "year" }, "axis": "bottom" },
          "xe": { "field": "Kalenderwoche", "type": "temporal" },
          "row": { "field": "year", "type": "nominal" },
          "color": { "field": "ARE_Konsultationsinzidenz", "type": "quantitative", "legend": true, "title": "ARE consultations per 100,000 per week", "range": "viridis" },
          "width": 1200,
          "height": 650
        }
      ]
    }
  ]
}
EOF
render spec.json

